const https = require\(''https''\);

const options = {
  hostname: ''api.smartsheet.com'',
  path: ''/2.0/sheets/8735086443712388?include=attachments'',
  headers: { ''Authorization'': ''Bearer '' + process.env.SMARTSHEET_API_TOKEN }
};

https.get\(options, res => {
  let data = '''';
  res.on\(''data'', chunk => data += chunk\);
  res.on\(''end'', \(\) => {
    const sheet = JSON.parse\(data\);

    // Count attachments at sheet level
    const sheetAttachments = sheet.attachments?.length || 0;

    // Count row-level attachments
    let rowAttachments = 0;
    const attachmentTypes = {};

    sheet.rows?.forEach\(row => {
      if \(row.attachments\) {
        rowAttachments += row.attachments.length;
        row.attachments.forEach\(a => {
          const ext = a.name?.split\(''.''\).pop\(\)?.toLowerCase\(\) || ''unknown'';
          attachmentTypes[ext] = \(attachmentTypes[ext] || 0\) + 1;
        }\);
      }
    }\);

    console.log\(''=== SMARTSHEET ATTACHMENTS ===''\);
    console.log\(''Sheet-level attachments:'', sheetAttachments\);
    console.log\(''Row-level attachments:'', rowAttachments\);
    console.log\(''Total:'', sheetAttachments + rowAttachments\);
    console.log\(''\\nBy file type:'', attachmentTypes\);
  }\);
}\);
")

