const fetch = require\(''node-fetch''\);

class OdooClient {
  constructor\(\) {
    this.url = ''https://velocityfibre.odoo.com'';
    this.db = ''velocityfibre'';
    this.uid = null;
  }

  async auth\(\) {
    const r = await fetch\(this.url + ''/jsonrpc'', {
      method: ''POST'',
      headers: { ''Content-Type'': ''application/json'' },
      body: JSON.stringify\({
        jsonrpc: ''2.0'', method: ''call'', id: 1,
        params: { service: ''common'', method: ''authenticate'', 
          args: [this.db, process.env.ODOO_USERNAME, process.env.ODOO_PASSWORD, {}] }
      }\)
    }\);
    this.uid = \(await r.json\(\)\).result;
    return this.uid;
  }

  async count\(model, domain = []\) {
    const r = await fetch\(this.url + ''/jsonrpc'', {
      method: ''POST'',
      headers: { ''Content-Type'': ''application/json'' },
      body: JSON.stringify\({
        jsonrpc: ''2.0'', method: ''call'', id: Date.now\(\),
        params: { service: ''object'', method: ''execute_kw'',
          args: [this.db, this.uid, process.env.ODOO_PASSWORD, model, ''search_count'', [domain]] }
      }\)
    }\);
    return \(await r.json\(\)\).result;
  }
}

